package com.tuowei.erp.finance.currency.controller;
import com.tuowei.erp.common.security.PermissionCodes; import com.tuowei.erp.common.web.ApiResponse; import com.tuowei.erp.finance.currency.service.CurrencyAdminService; import com.tuowei.erp.finance.currency.web.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/finance/currencies") public class CurrencyController {private final CurrencyAdminService service; public CurrencyController(CurrencyAdminService s){service=s;} @GetMapping @PreAuthorize(PermissionCodes.HAS_MASTERDATA_CURRENCY_VIEW) public ApiResponse<?> currencies(){return ApiResponse.success(service.currencies());} @GetMapping("/rates") @PreAuthorize(PermissionCodes.HAS_MASTERDATA_CURRENCY_VIEW) public ApiResponse<?> rates(@RequestParam(required=false) String from,@RequestParam(required=false) String to){return ApiResponse.success(service.rates(from,to));} @PostMapping("/rates") @PreAuthorize(PermissionCodes.HAS_MASTERDATA_CURRENCY_MANAGE) public ApiResponse<ExchangeRateResponse> create(@Valid @RequestBody ExchangeRateRequest request){return ApiResponse.success(service.create(request));}}
